    #[test]
    fn deferred_integrals_print_in_math_markup_modes() {
        let x = symbol!("x");
        let integral = rubi_symbols()
            .rubi_int
            .call((Atom::num(1) + Atom::var(x).pow(2), Atom::var(x)));

        assert_eq!(format!("{integral}"), "∫ 1+x^2 dx");
        assert_eq!(
            format!("{}", integral.printer(PrintOptions::latex())),
            "\\int 1+x^{2}\\,\\mathrm{d}x"
        );
        assert_eq!(
            format!("{}", integral.printer(PrintOptions::typst())),
            "integral 1+x^2 dif x"
        );

        let squared = integral.to_owned().pow(2);
        assert_eq!(
            format!("{}", squared.printer(PrintOptions::file_no_namespace())),
            "(∫ 1+x^2 dx)^2"
        );
        assert_eq!(
            format!("{}", squared.printer(PrintOptions::latex())),
            "\\left(\\int 1+x^{2}\\,\\mathrm{d}x\\right)^{2}"
        );
        assert_eq!(
            format!("{}", squared.printer(PrintOptions::typst())),
            "(integral 1+x^2 dif x)^2"
        );

        let exponent = Atom::num(2).pow(integral);
        assert_eq!(
            format!("{}", exponent.printer(PrintOptions::file_no_namespace())),
            "2^(∫ 1+x^2 dx)"
        );
        assert_eq!(
            format!("{}", exponent.printer(PrintOptions::latex())),
            "2^{\\int 1+x^{2}\\,\\mathrm{d}x}"
        );
        assert_eq!(
            format!("{}", exponent.printer(PrintOptions::typst())),
            "2^(integral 1+x^2 dif x)"
        );
    }

