    #[cfg(feature = "steps")]
    #[test]
    fn explanation_records_the_applied_rubi_transformation() {
        let x = symbol!("x");
        let integrand = parse!("x^2");
        let explanation = integrate_with_steps(integrand.as_view(), x);
        let primitive = explanation.result.expect("power rule should apply");

        assert_eq!(
            (primitive.derivative(x) - &integrand).expand(),
            Atom::num(0)
        );
        let first = explanation
            .steps
            .first()
            .expect("an explained integration should record its rule");
        assert_eq!(
            first.input,
            rubi_symbols().rubi_int.call((integrand, Atom::var(x)))
        );
        assert!(first.source.contains("Int["));
        assert!(!first.description.is_empty());
        assert_ne!(first.output, Atom::num(0));
    }

    #[cfg(feature = "steps")]
    #[test]
    fn deactivating_trig_reports_its_immediate_inert_integrand() {
        let x = symbol!("x");
        let integrand = parse!("x*sin(x)");
        let explanation = integrate_with_steps(integrand.as_view(), x);
        let first = explanation
            .steps
            .first()
            .expect("trigonometric preprocessing should be explained");

        assert_eq!(first.rule, Some(3042));
        let expected_input = rubi_symbols().rubi_int.call((integrand, Atom::var(x)));
        let expected_inert_integral = rubi_symbols()
            .rubi_int
            .call((Atom::var(x) * i_sin(Atom::var(x)), Atom::var(x)));
        assert_eq!(first.depth, 0);
        assert_eq!(first.input, expected_input);
        assert_eq!(first.output, expected_inert_integral);
        assert_eq!(
            first.description,
            "Rewrite trigonometric functions to Rubi's inert form before integrating."
        );

        let recurrence = explanation
            .steps
            .get(1)
            .expect("the inert sine product should use a recurrence");
        assert_eq!(recurrence.rule, Some(3777));
        assert_eq!(recurrence.depth, 1);
        assert_eq!(recurrence.input, first.output);
        assert_eq!(recurrence.output, parse!("-x*cos(x)+rubi_int(cos(x),x)"));
        assert_eq!(format!("{}", first.input), "∫ x*sin(x) dx");
        assert_eq!(format!("{}", recurrence.output), "-x*cos(x)+∫ cos(x) dx");

        let levels: Vec<_> = explanation.steps.iter().map(|step| step.depth).collect();
        assert_eq!(levels, vec![0, 1, 2, 3]);
        let rendered = explanation.to_string();
        assert!(rendered.starts_with("∫ x*sin(x) dx = ∫ x*rubi_sin(x) dx\n  ∫"));
        assert!(rendered.ends_with("= -x*cos(x)+sin(x)"));
    }

    #[cfg(feature = "steps")]
    #[test]
    fn int_sum_explanation_recurses_into_each_term() {
        let x = symbol!("x");
        let integrand = parse!("1-1/(1+x)");
        let explanation = integrate_with_steps(integrand.as_view(), x);
        let primitive = explanation
            .result
            .as_ref()
            .expect("the sum should be integrated");

        assert_eq!(primitive, &parse!("x-log(1+x)"));
        let sum = explanation
            .steps
            .first()
            .expect("IntSum should produce an explanation step");
        assert_eq!(sum.rule, Some(2009));
        assert_eq!(sum.depth, 0);
        assert!(sum.output.to_string().contains('∫'));
        assert!(explanation.steps.iter().skip(1).any(|step| step.depth == 1));
        assert!(
            explanation
                .steps
                .iter()
                .all(|step| step.description != "Variable substitution"),
            "ordinary recursive integration must not report a substitution"
        );
    }

    #[cfg(feature = "steps")]
    #[test]
    fn explanation_records_function_of_exponential_substitution() {
        let x = symbol!("x");
        let explanation = integrate_with_steps(parse!("exp(x)/(1+exp(x))").as_view(), x);
        let primitive = explanation
            .result
            .as_ref()
            .expect("the function-of-exponential substitution should integrate");

        assert_eq!(primitive, &parse!("log(1+exp(x))"));
        let substitution = explanation
            .steps
            .iter()
            .find(|step| step.description == "Variable substitution")
            .expect("the explanation should state the fresh-variable substitution");
        assert_eq!(substitution.rule, None);
        assert_eq!(substitution.input, Atom::var(rubi_symbols().sub1));
        assert_eq!(substitution.output, parse!("exp(x)"));
        assert!(explanation.to_string().contains("sub1 ="));
        assert_eq!(explanation.steps[1].description, "Variable substitution");
    }

