    #[test]
    fn shared_section_4_through_8_predicates_follow_rubi_definitions() {
        let x = symbol!("x");
        let y = symbol!("y");
        let x_atom = Atom::var(x);

        assert!(rubi_trig_q(&Atom::var(Symbol::SIN)));
        assert!(rubi_trig_q(&x_atom.cos()));
        assert!(!rubi_trig_q(&Atom::var(rubi_symbols().inert_sin)));
        assert!(!rubi_trig_q(&x_atom.sinh()));

        let int_x = rubi_symbols()
            .rubi_int
            .call((x_atom.sin(), x_atom.to_owned()));
        let int_y = rubi_symbols().rubi_int.call((x_atom.sin(), Atom::var(y)));
        assert!(!rubi_calculus_free_q(&int_x, x));
        assert!(rubi_calculus_free_q(&int_y, x));
        assert!(!rubi_calculus_free_q(
            &symbol!("Hold").call((x_atom.to_owned(),)),
            x
        ));

        assert!(igeq!(Atom::num(2), Atom::num(1)));
        assert!(!igeq!(Atom::num(1) / Atom::num(2), Atom::num(0)));
        assert!(rubi_independent_q(&parse!("a+b"), x));
        assert!(!rubi_independent_q(&parse!("a+b*x"), x));
    }

    #[test]
    fn binomial_parts_accepts_x_free_noninteger_and_symbolic_exponents() {
        let x = symbol!("x");

        let square_root = rubi_binomial_parts(parse!("sqrt(x)").as_view(), x)
            .expect("BinomialParts[x^(1/2),x] should return a list");
        assert_eq!(square_root.a, Atom::num(0));
        assert_eq!(square_root.b, Atom::num(1));
        assert_eq!(square_root.n, Atom::num(1) / Atom::num(2));

        let symbolic = rubi_binomial_parts(parse!("a+b*x^m").as_view(), x)
            .expect("BinomialParts[a+b*x^m,x] should return a list");
        assert_eq!(symbolic.a, parse!("a"));
        assert_eq!(symbolic.b, parse!("b"));
        assert_eq!(symbolic.n, parse!("m"));

        let product = rubi_binomial_parts(parse!("(1+x^m)*(1-x^m)").as_view(), x)
            .expect("the matching-exponent Product branch should combine binomials");
        assert_eq!(product.a, Atom::num(1));
        assert_eq!(product.b, Atom::num(-1));
        assert_eq!(product.n, Atom::num(2) * parse!("m"));

        assert!(rubi_binomial_match_q(&parse!("a+b*x^m"), x));
        assert!(!rubi_binomial_match_q(&parse!("a+b*x^m+c*x^n"), x));
    }

    #[test]
    fn inverse_function_of_linear_follows_rubi_scan_and_match_guards() {
        let x = symbol!("x");
        let witness = parse!("a^b*atan(x)");

        assert!(rubi_has_free_base_power(witness.as_view(), x));
        assert!(
            rubi_inverse_linear_quadratic_match(
                &witness,
                &parse!("1+x^2"),
                x,
                RubiInverseKind::ArcTan,
            )
            .is_some()
        );

        let earlier_other_inverse = symbol!("f").call((parse!("asin(x)"), parse!("atan(x)")));
        assert!(
            rubi_inverse_function_of_linear(&earlier_other_inverse, x, RubiInverseKind::ArcTan,)
                .is_none(),
            "Rubi returns the first inverse function and then rejects its head"
        );

        let held_in_calculus = rubi_symbols()
            .rubi_int
            .call((parse!("atan(x)"), Atom::var(x)));
        assert!(
            rubi_inverse_function_of_linear(&held_in_calculus, x, RubiInverseKind::ArcTan)
                .is_none()
        );
    }

