    fn residual_is_zero(residual: &Atom) -> bool {
        let residual = normalize_pi_half_trig_for_verification(residual).together();
        if residual.is_zero() || !matches!(residual.zero_test(8, 1e-10), ConditionResult::False) {
            return true;
        }

        let mut normalized = residual.to_owned();
        for _ in 0..3 {
            normalized = normalize_pi_half_trig_for_verification(
                &expand_reciprocals_for_verification(&normalized),
            )
            .together();
            if normalized.is_zero()
                || !matches!(normalized.zero_test(8, 1e-10), ConditionResult::False)
            {
                return true;
            }
        }

        false
    }

