    fn normalize_pi_half_trig_for_verification(expr: &Atom) -> Atom {
        match expr.as_view() {
            AtomView::Fun(function)
                if function.get_nargs() == 1
                    && rubi_inert_or_builtin_trig_symbol_q(function.get_symbol()) =>
            {
                let argument = normalize_pi_half_trig_for_verification(&function.get(0).to_owned());
                if let Some((base, shift)) = pi_half_shift_base_for_verification(&argument) {
                    return trig_pi_half_shift_for_verification(function.get_symbol(), base, shift);
                }
                function.get_symbol().call((argument,))
            }
            AtomView::Fun(function) => {
                let args: Vec<_> = function
                    .into_iter()
                    .map(|argument| normalize_pi_half_trig_for_verification(&argument.to_owned()))
                    .collect();
                function.get_symbol().call_args(args)
            }
            AtomView::Add(add) => add
                .into_iter()
                .map(|term| normalize_pi_half_trig_for_verification(&term.to_owned()))
                .fold(Atom::num(0), |sum, term| sum + term),
            AtomView::Mul(mul) => mul
                .into_iter()
                .map(|factor| normalize_pi_half_trig_for_verification(&factor.to_owned()))
                .fold(Atom::num(1), |product, factor| product * factor),
            AtomView::Pow(power) => {
                normalize_pi_half_trig_for_verification(&power.get_base().to_owned()).pow(
                    normalize_pi_half_trig_for_verification(&power.get_exp().to_owned()),
                )
            }
            AtomView::Num(_) | AtomView::Var(_) => expr.to_owned(),
        }
    }

    fn pi_half_shift_base_for_verification(argument: &Atom) -> Option<(Atom, i8)> {
        let pi = Atom::var(Symbol::PI);
        let pi_over_two = Atom::var(Symbol::PI) / 2;
        match argument.as_view() {
            AtomView::Add(add) => {
                for term in add {
                    let term = term.to_owned();
                    if eqq!(term, pi) {
                        return Some(((argument - &term).expand(), 2));
                    }
                    if eqq!(term, -&pi) {
                        return Some(((argument - &term).expand(), -2));
                    }
                    if eqq!(term, pi_over_two) {
                        return Some(((argument - &term).expand(), 1));
                    }
                    if eqq!(term, -&pi_over_two) {
                        return Some(((argument - &term).expand(), -1));
                    }
                }
                None
            }
            _ => None,
        }
    }

    fn trig_pi_half_shift_for_verification(symbol: Symbol, base: Atom, shift: i8) -> Atom {
        match (symbol, shift) {
            (s, 1) if s == Symbol::SIN => base.cos(),
            (s, -1) if s == Symbol::SIN => -base.cos(),
            (s, 2 | -2) if s == Symbol::SIN => -base.sin(),
            (s, 1) if s == Symbol::COS => -base.sin(),
            (s, -1) if s == Symbol::COS => base.sin(),
            (s, 2 | -2) if s == Symbol::COS => -base.cos(),
            (s, 2 | -2) if s == symbolica::transcendental::tan() => base.tan(),
            (s, 2 | -2) if s == symbolica::transcendental::cot() => base.cot(),
            (s, _) if s == symbolica::transcendental::tan() => -base.cot(),
            (s, _) if s == symbolica::transcendental::cot() => -base.tan(),
            (s, 1) if s == symbolica::transcendental::sec() => -base.csc(),
            (s, -1) if s == symbolica::transcendental::sec() => base.csc(),
            (s, 2 | -2) if s == symbolica::transcendental::sec() => -base.sec(),
            (s, 1) if s == symbolica::transcendental::csc() => base.sec(),
            (s, -1) if s == symbolica::transcendental::csc() => -base.sec(),
            (s, 2 | -2) if s == symbolica::transcendental::csc() => -base.csc(),
            _ => symbol.call((base,)),
        }
    }

    fn downvalue_primitive(order: u16, integrand: &Atom, x: Symbol) -> Atom {
        let rule = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(order))
            .unwrap_or_else(|| panic!("Rubi DownValue {order} should exist"));
        matcher_rule_for_test(integrand, x, rule)
            .unwrap_or_else(|| panic!("Rubi DownValue {order} should apply to {integrand}"))
    }

