    fn integrates_mixed_linear_sin_cos_product_via_expand_trig_reduce() {
        let x = symbol!("x");
        let integrand = parse!("cos(x)*sin(a+x)");
        let reduced = rubi_expand_trig_reduce_one(&integrand, x);
        let expected_reduction = parse!("1/2*sin(a)+1/2*sin(a+2*x)");
        let reduction_difference = (reduced - expected_reduction).expand().cancel();

        assert!(
            residual_is_zero(&reduction_difference),
            "ExpandTrigReduce should match Mathematica's product-to-sum path: {reduction_difference}"
        );
        let generated_x = Symbol::parse("x", "rubi_generated").unwrap();
        let generated_shape =
            Atom::parse("sin(x+a)*cos(x)", "rubi_generated", Default::default()).unwrap();
        let generated_reduced =
            rubi_expand_trig_reduce_one(&rubi_activate_trig(&generated_shape), generated_x);
        let generated_expected = Atom::parse(
            "1/2*sin(a)+1/2*sin(a+2*x)",
            "rubi_generated",
            Default::default(),
        )
        .unwrap();
        let generated_difference = (generated_reduced - generated_expected).expand().cancel();
        assert!(
            residual_is_zero(&generated_difference),
            "ActivateTrig should canonicalize wildcard trig heads before ExpandTrigReduce: {generated_difference}"
        );
        assert_derivative_round_trip(integrand);
    }

