    #[test]
    fn expand_trig_reduce_matches_mathematica_product_to_sum_family() {
        let x = symbol!("x");
        for (input, expected) in [
            ("sin(x+a)*sin(x)", "1/2*cos(a)-1/2*cos(a+2*x)"),
            ("cos(x+a)*cos(x)", "1/2*cos(a)+1/2*cos(a+2*x)"),
            ("sin(x+a)*cos(x+b)", "1/2*sin(a-b)+1/2*sin(a+b+2*x)"),
            (
                "sin(x+a)*cos(x)*cos(2*x)",
                "1/4*sin(a)+1/4*sin(a-2*x)+1/4*sin(a+2*x)+1/4*sin(a+4*x)",
            ),
            (
                "cosh(x)*cosh(2*x)*cosh(3*x)",
                "1/4+1/4*cosh(2*x)+1/4*cosh(4*x)+1/4*cosh(6*x)",
            ),
            ("sinh(x)^3", "1/4*sinh(3*x)-3/4*sinh(x)"),
            ("cosh(x)^3", "1/4*cosh(3*x)+3/4*cosh(x)"),
            ("sinh(x)^4", "3/8-1/2*cosh(2*x)+1/8*cosh(4*x)"),
        ] {
            let reduced = rubi_expand_trig_reduce_one(&parse!(input), x);
            let difference = (reduced - parse!(expected)).expand().cancel();
            assert!(
                residual_is_zero(&difference),
                "ExpandTrigReduce mismatch for {input}: {difference}"
            );
        }
    }

