    #[test]
    fn generalized_current_rows_cover_removed_inverse_and_log_specializations() {
        let x = symbol!("x");
        let cases = [
            (6190, parse!("(1+asinh(2*x))/x")),
            (2842, parse!("x^2*(1+log(3*(4+5*x)^2))")),
        ];

        for (order, integrand) in cases {
            let rule = rubi_rules()
                .iter()
                .find(|rule| rule.downvalue_order == Some(order))
                .unwrap_or_else(|| panic!("Rubi DownValue {order} should be ported"));
            let primitive = matcher_rule_for_test(&integrand, x, rule)
                .unwrap_or_else(|| panic!("Rubi DownValue {order} should cover {integrand}"));
            assert!(
                rubi_integral_free_q(&primitive) && !rubi_contains_unintegrable(&primitive),
                "Rubi DownValue {order} left an internal integral for {integrand}: {primitive}"
            );
        }
    }

