    #[test]
    fn simp_evaluates_equivalent_shifted_imaginary_trig_calls() {
        let x = symbol!("x");
        let argument = parse!("c+d*x");
        let imaginary_argument = Atom::i() * &argument;
        let shifted_argument = Atom::var(Symbol::PI) / 2 + &imaginary_argument;
        let expr = (parse!("a") + parse!("b") * imaginary_argument.sec())
            * (parse!("A")
                + parse!("B") * shifted_argument.csc()
                + parse!("C") * shifted_argument.csc().pow(2));

        assert_eq!(
            rubi_simp(&expr, x),
            parse!("(a+b*sech(c+d*x))*(A+B*sech(c+d*x)+C*sech(c+d*x)^2)")
        );

        let integrand = parse!("(a+b*sech(c+d*x))^4");
        let primitive = integrate(&integrand, x)
            .expect("Rubi's DeactivateTrig recurrence should integrate the sech power");
        assert!(
            rubi_integral_free_q(&primitive) && !rubi_contains_unintegrable(&primitive),
            "DeactivateTrig recurrence should not defer: {primitive}"
        );
        assert!(
            rubi_inert_trig_free_q(&primitive),
            "finished primitive should reactivate inert trig heads: {primitive}"
        );
        assert_rubi_derivative_round_trip(integrand);
    }

