    #[test]
    fn subst_for_factor_normalizes_tangent_payload_like_rubi_charlwood_20_trace() {
        let t = symbol!("t");
        let x = symbol!("x");
        let integrand = parse!("cos(x)^2/sqrt(1+cos(x)^2+cos(x)^4)");
        let reciprocal_sum = parse!("1+1/(1+t^2)+1/(1+t^2)^2");
        let together = rubi_together_simplify(&reciprocal_sum);
        let expected_together = parse!("(3+3*t^2+t^4)/(1+t^2)^2");
        assert_eq!(
            together, expected_together,
            "TogetherSimplify should match IntegrationUtilityFunctions.m NormalizeIntegrandFactorBase"
        );
        let normalized_base = rubi_normalize_integrand_factor_base(&reciprocal_sum, t);
        assert_eq!(
            normalized_base,
            expected_together,
            "NormalizeIntegrandFactorBase should accept TogetherSimplify (source leaf counts: 16 -> 18; Rust leaf counts: {} -> {})",
            rubi_leaf_count(reciprocal_sum.as_view()),
            rubi_leaf_count(together.as_view()),
        );
        let transformed =
            rubi_subst_for_factor(&parse!("1/(1+t^2)"), &parse!("tan(x)"), &integrand, t);
        let expected = parse!("1/((1+t^2)^2*((3+3*t^2+t^4)/(1+t^2)^2)^(1/2))");
        let difference = (transformed.to_owned() - expected.to_owned()).together();

        assert!(
            transformed == expected,
            "SubstFor should preserve Mathematica's rule-7270 payload shape; got {transformed}; algebraic difference: {difference}"
        );

        let primitive =
            integrate(&integrand, x).expect("Rubi elliptic rules should integrate Charlwood 20");
        assert!(
            rubi_integral_free_q(&primitive),
            "Charlwood 20 should reach Rubi elliptic rows instead of a deferred Int: {primitive}"
        );
    }

    #[test]
    fn subst_for_factor_keeps_timofeev_566_tangent_power_compact() {
        let t = symbol!("t");
        let integrand = parse!("1/(cos(x)^11*sin(x)^13)^(1/4)");
        let substituted = rubi_subst_for(&integrand, &parse!("tan(x)"), t);
        assert_eq!(substituted, parse!("1/(t^13/(1+t^2)^12)^(1/4)"));
        let weighted = parse!("1/(1+t^2)") * &substituted;
        let expected = parse!("1/((t^13/(1+t^2)^12)^(1/4)*(1+t^2))");
        assert_eq!(weighted, expected);
        assert_eq!(
            rubi_simplify_rational_subexpressions(&weighted, t),
            expected
        );
        assert_eq!(rubi_normalize_integrand_aux(&weighted, t), expected);
        assert_eq!(rubi_mathematica_simplify(&weighted), expected);
        assert_eq!(
            rubi_simplify_integrand_mathematica_simplify_candidate(&weighted, t),
            None
        );
        assert_eq!(
            rubi_simplify_integrand_normalized_candidate(&weighted, t),
            None
        );

        let transformed =
            rubi_subst_for_factor(&parse!("1/(1+t^2)"), &parse!("tan(x)"), &integrand, t);
        assert_eq!(transformed, expected);
    }

    #[test]
    fn subst_for_factor_matches_timofeev_606_numeric_radical_content() {
        let t = symbol!("t");
        let x = symbol!("x");
        let simplified_trig = parse!("sec(x)^2*(-cos(2*x)+2*tan(x)^2)/(-1+sec(2*x))^(3/2)");
        let deactivated = rubi_deactivate_trig(&simplified_trig, x);
        let transformed =
            rubi_subst_for_factor(&parse!("1/(1+t^2)"), &parse!("tan(x)"), &deactivated, t);
        let expected = parse!("sqrt(1/8)*(-1+3*t^2+2*t^4)/((t^2/(1-t^2))^(3/2)*(1+t^2))");

        assert_eq!(
            transformed, expected,
            "Mathematica SubstFor pulls positive numeric content out of the fractional power"
        );
        let rule_2058 = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(2058))
            .expect("Rubi rule 2058 is loaded");
        let free_factor = rubi_free_factors(&transformed, t);
        assert_eq!(free_factor, parse!("sqrt(1/8)"));
        let without_free_factor = transformed / free_factor;
        assert!(
            matcher_rule_for_test(&without_free_factor, t, rule_2058).is_some(),
            "the normalized Timofeev 606 payload must dispatch to source rule 2058"
        );
    }

