    #[test]
    fn timofeev_801_function_of_trig_guard_matches_mathematica() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let i = Atom::i();
        let ix = &i * &x_atom;
        let v = Atom::num(2) * &ix;
        let u = (-i_cos(v.to_owned()) - &i * i_tan(ix.to_owned())) * i_cos(ix.to_owned())
            / (-&i * i_sin(v.to_owned()) - i_sin(ix.to_owned()).pow(2));
        let m = -Atom::num(1) / Atom::num(2);
        let c = -i;
        let seed = u * (&v / 2).sin().pow(2 * &m) / (c * (&v / 2).tan()).pow(&m);
        let w = rubi_function_of_trig(&seed, x)
            .expect("Mathematica FunctionOfTrig returns I*x for the DownValue 4890 seed");
        let nonfree = rubi_nonfree_factors(&rubi_activate_trig(&w.tan()), x);

        assert_eq!(w, Atom::i() * x_atom);
        assert_eq!(nonfree, parse!("tanh(x)"));
        assert!(
            rubi_function_of_q(&nonfree, &seed, x),
            "Mathematica FunctionOfQ[Tanh[x], seed, x] is true"
        );
    }

