    #[test]
    fn deactivated_hyperbolic_products_pass_rubi_sine_substitution_guard() {
        let x = symbol!("x");

        for (integrand, sine_substitution) in [
            (parse!("sinh(x)*tanh(6*x)"), true),
            (parse!("cosh(x)*tanh(6*x)"), false),
            (parse!("sinh(x)*coth(6*x)"), true),
            (parse!("cosh(x)*coth(6*x)"), false),
        ] {
            let inactive = rubi_deactivate_trig(&integrand, x);
            let payload = rubi_nonfree_factors(&inactive, x);
            let v = rubi_function_of_trig(&payload, x)
                .expect("FunctionOfTrig should find the common imaginary-linear argument");
            let sin = rubi_mathematica_evaluate_active_trig_call(Symbol::SIN, v.to_owned());
            let cos = rubi_mathematica_evaluate_active_trig_call(Symbol::COS, v.to_owned());
            let (base, quotient) = if sine_substitution {
                (rubi_nonfree_factors(&sin, x), &payload / cos)
            } else {
                (rubi_nonfree_factors(&cos, x), &payload / sin)
            };

            assert!(
                rubi_function_of_q(&base, &quotient, x),
                "Rubi DownValue 4878/4879 accepts {integrand}; inactive={inactive}, payload={payload}, v={v}, base={base}, quotient={quotient}"
            );
        }
    }

