    #[test]
    fn integrates_formal_derivative_64_via_rubi_simp_cancellation() {
        let x = symbol!("x");
        let b = parse!("b");
        let angle = parse!("a+b*x");
        let f = symbol!("f");
        let f_x = f.call(Atom::var(x));
        let derivative_1 = rubi_derivative(Atom::num(1), Atom::var(f), x);
        let derivative_2 = rubi_derivative(Atom::num(2), Atom::var(f), x);
        let derivative_3 = rubi_derivative(Atom::num(3), Atom::var(f), x);
        assert_eq!(derivative_1.derivative(x), derivative_2);
        let deferred = rubi_unintegrable(angle.cos() * &f_x, x);
        let traced_int_sum = angle.sin() * &derivative_2
            - (&b * angle.cos() * &derivative_1 + b.pow(2) * angle.sin() * &f_x
                - b.pow(3) * &deferred)
            - b.pow(3) * deferred;
        let expected = -b.pow(2) * &f_x * angle.sin() - &b * angle.cos() * derivative_1
            + angle.sin() * derivative_2;
        assert_eq!(rubi_simp(&traced_int_sum, x), expected);

        let integrand = -b.pow(3) * angle.cos() * f_x + angle.sin() * derivative_3;
        let primitive = integrate(&integrand, x)
            .expect("formal derivative line 64 should follow Rubi DownValues 2009/7213/7214");

        assert_eq!(primitive, expected);
    }

