    #[test]
    fn function_of_q_uses_shared_function_of_expn_q_like_rubi() {
        let x = symbol!("x");

        assert!(
            !rubi_function_of_q(&parse!("1/x"), &parse!("sqrt(x+sqrt(1+x))"), x),
            "Rubi FunctionOfQ[1/x, Sqrt[x+Sqrt[1+x]], x] is False"
        );
        assert!(
            rubi_function_of_q(&parse!("1/x"), &parse!("sqrt(1/x+sqrt(1+1/x))"), x),
            "Rubi FunctionOfQ[x^-1, Sqrt[x^-1+Sqrt[1+x^-1]], x] is True"
        );
        assert!(
            !rubi_function_of_q(&parse!("x^2"), &parse!("sqrt(1/x+sqrt(1+1/x))"), x),
            "Rubi FunctionOfQ[x^2, Sqrt[x^-1+Sqrt[1+x^-1]], x] is False"
        );
        assert!(
            !rubi_function_of_q(&rubi_product_log(Atom::var(x)), &parse!("exp(exp(x)+x)"), x),
            "Rubi FunctionOfQ[ProductLog[x], E^(E^x+x), x] is False"
        );
        assert!(
            !rubi_function_of_q(
                &rubi_product_log(Atom::var(x)),
                &parse!("(a^(k*x)+a^(l*x))^2"),
                x,
            ),
            "Rubi FunctionOfQ[ProductLog[x], (a^(k*x)+a^(l*x))^2, x] is False"
        );
        assert!(
            rubi_function_of_q(&parse!("x^2"), &parse!("asin(x^2)"), x),
            "Rubi FunctionOfQ[x^2, ArcSin[x^2], x] is True"
        );
        assert!(
            rubi_function_of_q(&parse!("x^2"), &parse!("1/sqrt(-1+exp(2*x^2))"), x),
            "Rubi FunctionOfQ[x^2, 1/Sqrt[-1+E^(2*x^2)], x] is True"
        );
        assert!(
            rubi_function_of_q(
                &parse!("tanh(x)"),
                &parse!("sinh(x)*cosh(x)+cosh(2*x)^2"),
                x,
            ),
            "Rubi FunctionOfTanhQ accepts paired odd hyperbolic factors and even multiples"
        );
        assert!(
            rubi_function_of_q(
                &parse!("tan(a+b*x)"),
                &parse!("(cos(a+b*x)^5-sin(a+b*x)^5)/(cos(a+b*x)^5+sin(a+b*x)^5)"),
                x,
            ),
            "Rubi FunctionOfTanQ accepts paired odd trig-power sums"
        );
        assert!(
            !rubi_function_of_q(
                &parse!("tanh(x)"),
                &parse!("cosh(x)*(-cosh(2*x)+tanh(x))/(sqrt(sinh(2*x))*(sinh(x)^2+sinh(2*x)))"),
                x,
            ),
            "Rubi FunctionOfTanhQ rejects Timofeev 801 before fractional-power normalization"
        );
        assert!(
            !rubi_calculus_function_symbol(symbol!("asin"))
                && !rubi_calculus_function_symbol(symbol!("sech"))
                && !rubi_calculus_function_symbol(symbol!("log")),
            "Rubi CalculusQ excludes elementary and inverse functions"
        );
    }

