    #[test]
    fn apostol_19_follows_rubi_downvalue_3147_after_deactivate_trig() {
        let x = symbol!("x");
        let active_integrand = parse!("sin(x)/(3+cos(x))^2");
        let deactivated = rubi_deactivate_trig(&active_integrand, x);
        let expected_deactivated =
            rubi_inertize_builtin_trig_heads(&parse!("cos(x-pi/2)/(3-sin(x-pi/2))^2"));
        assert_eq!(
            deactivated, expected_deactivated,
            "Rubi DeactivateTrig should apply its UnifyInertTrigFunction phase shift"
        );

        let primitive = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(3147))
            .and_then(|rule| matcher_rule_for_test(&deactivated, x, rule))
            .expect("Rubi DownValue 3147 should match Apostol Problems.input line 19");
        let primitive = rubi_activate_trig(&primitive);
        let expected = parse!("1/(3+cos(x))");
        let primitive_difference = (primitive.to_owned() - expected.to_owned()).together();
        let residual = (primitive.derivative(x) - active_integrand.to_owned()).together();

        assert!(
            residual_is_zero(&primitive_difference),
            "primitive should match Rubi trace result up to simplification: {primitive_difference}"
        );
        assert!(
            residual_is_zero(&residual),
            "primitive derivative mismatch: {residual}"
        );

        let full_primitive = integrate(&active_integrand, x)
            .expect("Apostol line 19 should integrate through Rubi's DeactivateTrig path");
        let full_difference = (full_primitive.to_owned() - expected).together();
        let full_residual = (full_primitive.derivative(x) - active_integrand).together();
        assert!(
            residual_is_zero(&full_difference),
            "full integration primitive should match Rubi trace result up to simplification: {full_difference}"
        );
        assert!(
            residual_is_zero(&full_residual),
            "full integration derivative mismatch: {full_residual}"
        );
    }

