    #[test]
    fn fixes_inert_trig_reciprocal_product_rows() {
        let x = symbol!("x");
        let inert = |expr: Atom| rubi_inertize_builtin_trig_heads(&expr);
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("csc(x)^2*sin(x)^3")), x),
            inert(parse!("sin(x)"))
        );
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("sec(x)^2*cos(x)^3")), x),
            inert(parse!("cos(x)"))
        );
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("x*tan(x)^2*(1+sin(x))")), x),
            inert(parse!("x*sin(x)^2*cos(x)^(-2)*(1+sin(x))"))
        );
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("sec(x)^2*(1+cos(x))")), x),
            inert(parse!("cos(x)^(-2)*(1+cos(x))"))
        );
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("cos(x)^2*(1+2*sec(x)+3*sec(x)^2)")), x),
            inert(parse!("sec(x)^(-2)*(1+2*sec(x)+3*sec(x)^2)"))
        );
        assert_eq!(
            rubi_fix_inert_trig_function(&inert(parse!("sec(x)^2*(1+2*cos(x)+3*cos(x)^2)^3")), x),
            inert(parse!("cos(x)^(-2)*(1+2*cos(x)+3*cos(x)^2)^3"))
        );
    }

    #[test]
    fn unifies_inert_secant_to_cosecant_rows() {
        let x = symbol!("x");
        let inert = |expr: Atom| rubi_inertize_builtin_trig_heads(&expr);
        assert_eq!(
            rubi_unify_inert_trig_function(&inert(parse!("(1+sec(x))^2")), x),
            inert(parse!("(1+csc(x+1/2*pi))^2"))
        );
        assert_eq!(
            rubi_unify_inert_trig_function(
                &inert(parse!("(b*sec(c+d*x))^(1/3)*(A+C*sec(c+d*x)^2)")),
                x,
            ),
            inert(parse!(
                "(b*csc(c+1/2*pi+d*x))^(1/3)*(A+C*csc(c+1/2*pi+d*x)^2)"
            ))
        );
        assert_eq!(
            rubi_unify_inert_trig_function(
                &inert(parse!(
                    "(a*cos(x)+b)^(3/2)*(c*cos(x)+d)^(-7/2)*(A+B*cos(x)+C*cos(x)^2)"
                )),
                x,
            ),
            inert(parse!(
                "(a*sin(x+1/2*pi)+b)^(3/2)*(c*sin(x+1/2*pi)+d)^(-7/2)*(A+B*sin(x+1/2*pi)+C*sin(x+1/2*pi)^2)"
            ))
        );
    }

