    #[test]
    fn polynomial_division_removes_algebraic_zero_leading_terms() {
        let x = symbol!("x");
        let numerator = parse!("sqrt(3) - 2*x - 2*x^3 - sqrt(3)*x^4");
        let denominator = parse!("2 - sqrt(3) + 2*(1 + sqrt(3))*x + sqrt(3)*x^2");
        let (quotient, remainder) = polynomial_quotient_remainder(&numerator, &denominator, x)
            .expect("polynomial division with algebraic coefficients should apply");
        let residual = (&quotient * &denominator + &remainder - &numerator).expand();

        assert!(
            rubi_algebraic_zero_q(&residual),
            "quotient/remainder should reconstruct the numerator; residual: {residual}"
        );
        assert!(
            polynomial_degree(&remainder, x)
                .zip(polynomial_degree(&denominator, x))
                .is_some_and(|(remainder_degree, denominator_degree)| {
                    remainder_degree < denominator_degree
                }),
            "remainder degree should be lower than denominator degree; remainder: {remainder}"
        );
    }

    #[test]
    fn polynomial_division_handles_rational_dividends_like_mathematica() {
        let x = symbol!("x");
        let numerator = parse!("(d+e*x)^3");
        let rational_denominator = parse!("(f+g*x)^2");
        let polynomial_divisor = parse!("d^2-e^2*x^2");
        let (quotient, remainder) = polynomial_quotient_remainder_rational_dividend(
            &numerator,
            &rational_denominator,
            &polynomial_divisor,
            x,
        )
        .expect("Mathematica PolynomialQuotient/PolynomialRemainder semantics should apply");
        let residual =
            (&numerator / &rational_denominator - &quotient * &polynomial_divisor - &remainder)
                .together();

        assert!(
            rubi_algebraic_zero_q(&residual),
            "rational quotient/remainder should reconstruct the dividend: {residual}"
        );
        assert_eq!(polynomial_degree(&remainder, x), Some(1));
    }

    #[test]
    fn polynomial_quotient_wrappers_accept_laurent_dividends_like_mathematica() {
        let x = symbol!("x");
        let dividend = parse!("(-3*A+3*A*b*x^2/a-3*B*x+2*B*b*x^3/a)/x^3");
        let divisor = parse!("a+b*x^2");

        assert_eq!(
            rubi_polynomial_quotient(&dividend, &divisor, x)
                .expect("Mathematica accepts the Laurent dividend")
                .together(),
            parse!("(-3*A-3*B*x+6*A*b*x^2/a)/(a*x^3)").together()
        );
        assert_eq!(
            rubi_polynomial_remainder(&dividend, &divisor, x)
                .expect("Mathematica returns a polynomial remainder")
                .together(),
            parse!("5*b*B/a-6*A*b^2*x/a^2").together()
        );
    }

    #[test]
    fn polynomial_division_cancels_rational_polynomial_factors_like_mathematica() {
        let x = symbol!("x");
        let dividend = parse!("(1+x^2)*(-4*a-3*b+2*b/(1+x^2))");
        let divisor = parse!("a+b+a*x^2");

        assert_eq!(
            rubi_polynomial_quotient(&dividend, &divisor, x)
                .expect("Mathematica cancels the rational factor before polynomial division")
                .together(),
            parse!("-4-3*b/a").together()
        );
        assert_eq!(
            rubi_polynomial_remainder(&dividend, &divisor, x)
                .expect("Mathematica returns the polynomial remainder after cancellation")
                .together(),
            parse!("6*b+3*b^2/a").together()
        );
    }

