    #[test]
    fn conditional_match_q_supports_rubi_nested_optional_polynomial_factor() {
        let x = symbol!("x");
        let symbols = rubi_symbols();
        let pattern = Atom::var(symbols.qx__)
            * (Atom::var(symbols.c__)
                + Atom::var(symbols.d__) * Atom::var(x).pow(Atom::var(symbols.m_)))
            .pow(Atom::var(symbols.q_));
        let expression = parse!("(1+x)*(3+5*x^3)^2");

        assert!(rubi_conditional_match_q(
            &expression,
            pattern,
            &[symbols.qx__, symbols.d__],
            |matches| {
                wildcard_atom(matches, symbols.qx__) == Some(parse!("1+x"))
                    && wildcard_atom(matches, symbols.c__) == Some(Atom::num(3))
                    && wildcard_atom(matches, symbols.d__) == Some(Atom::num(5))
                    && wildcard_atom(matches, symbols.m_) == Some(Atom::num(3))
                    && wildcard_atom(matches, symbols.q_) == Some(Atom::num(2))
            },
        ));
    }

