    #[test]
    fn matches_rubi_8_6_affine_incomplete_gamma() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let a = Atom::var(symbol!("a"));
        let b = Atom::var(symbol!("b"));
        let m = Atom::var(symbol!("m"));
        let n = Atom::var(symbol!("n"));
        let p = Atom::var(symbol!("p"));
        let integrand = rubi_gamma(1 + p, -&a * (1 + &m) / (&b * &n) - x_atom * (1 + m) / n);
        let rule = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(7111))
            .expect("latest Rubi incomplete-Gamma affine rule should be registered");

        assert!(
            matcher_rule_for_test(&integrand, x, rule).is_some(),
            "latest Rubi rule 7111 should match an affine incomplete-Gamma argument"
        );
        assert!(
            integrate(&integrand, x).is_ok(),
            "the full rule scan should reach latest Rubi rule 7111"
        );
    }

