    #[test]
    fn matches_negative_quartic_inverse_sqrt_negative_a_elliptic_f_rows() {
        let x = symbol!("x");
        let integrand = parse!("1/sqrt(-1 + x^4)");
        let mut matching_rows = rubi_rules()
            .iter()
            .filter(|rule| matches!(rule.downvalue_order, Some(763 | 764)));
        let first_rule = matching_rows
            .next()
            .expect("block 33 integer-q EllipticF row should apply");
        let second_rule = matching_rows
            .next()
            .expect("block 33 general EllipticF row should apply");

        let first = matcher_rule_for_test(&integrand, x, first_rule)
            .expect("block 33 integer-q EllipticF row should apply");
        let second = matcher_rule_for_test(&integrand, x, second_rule)
            .expect("block 33 general EllipticF row should apply");

        assert!(format!("{first}").contains("elliptic_f"));
        assert!(format!("{second}").contains("elliptic_f"));
    }

