    #[test]
    fn matches_downvalues_856_through_863_source_substitutions() {
        let x = symbol!("x");
        let cases = [
            (856, parse!("x*(1+x^3)^(-2/3)")),
            (857, parse!("x*(1+x^3)^(-1/3)*(1-x^3)^(-1/3)")),
            (858, parse!("x*(1+x^-2)^2")),
            (859, parse!("x*(1+x^-2)^2*(1-x^-2)^2")),
            (860, parse!("(2*x)^(1/2)*(1+x^-2)^2")),
            (861, parse!("x^(1/2)*(1+x^-2)^2*(1-x^-2)^2")),
            (862, parse!("(2*x)^q*(1+x^-2)^2")),
            (863, parse!("(2*x)^q*(1+x^-2)^2*(1-x^-2)^2")),
        ];

        for (order, integrand) in cases {
            let primitive = downvalue_primitive(order, &integrand, x);
            assert!(
                !primitive.is_zero(),
                "Rubi DownValue {order} should produce its source substitution payload"
            );
        }
    }

