    #[test]
    fn integrates_line41_generated_quadratic_log_partial_fraction_sum() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let quadratic = x_atom.pow(2) + &x_atom - 1;
        let quadratic_log = quadratic.log();
        let integrand = Atom::num(1) / Atom::num(2) * &quadratic_log / (Atom::num(1) + &x_atom)
            + Atom::num(1) / Atom::num(2) * &quadratic_log / (-Atom::num(1) + &x_atom);
        let primitive = integrate_generated_payload(&integrand, x).unwrap_or_else(|| {
            panic!("generated partial-fraction sum should integrate: {integrand}")
        });

        assert!(
            !rubi_contains_unintegrable(&primitive),
            "generated partial-fraction sum should not return unintegrable: {primitive}"
        );
    }

