    #[test]
    fn integrates_polylog_regression_rule() {
        assert_derivative_round_trip(parse!("polylog(2, x)"));
        assert_derivative_round_trip(parse!("log(1 - 2*x)/x"));
        assert_derivative_round_trip(parse!("polylog(2, x)/x"));
        assert_derivative_round_trip(parse!("polylog(2, 3*x)/x"));
        assert_derivative_round_trip(parse!("polylog(2, 3*x^2)/x"));
        assert_derivative_round_trip(parse!("polylog(3, 3*x^2)/x"));
        assert_derivative_round_trip(parse!("polylog(2, 5*(2^(3*(1 + 7*x)))^11)"));
        assert_derivative_round_trip(parse!("polylog(2, 3*x)"));
        assert_derivative_round_trip(parse!("polylog(3, 3*x)"));
        assert_derivative_round_trip(parse!("polylog(2, 3*x^2)"));
        assert_derivative_round_trip(parse!("polylog(3, 3*x^2)"));
        assert_derivative_round_trip(parse!("x*polylog(2, 3*x)"));
        assert_derivative_round_trip(parse!("x^2*polylog(2, 3*x)"));
        assert_derivative_round_trip(parse!("x^3*polylog(2, 3*x)"));
        assert_derivative_round_trip(parse!("x^4*polylog(2, 3*x)"));
        assert_derivative_round_trip(parse!("x*polylog(3, 3*x)"));
        assert_derivative_round_trip(parse!("x^2*polylog(3, 3*x)"));
        assert_derivative_round_trip(parse!("x^3*polylog(3, 3*x)"));
        assert_derivative_round_trip(parse!("x*polylog(2, 3*x^2)"));
        assert_derivative_round_trip(parse!("x^3*polylog(2, 3*x^2)"));
        assert_derivative_round_trip(parse!("x^5*polylog(2, 3*x^2)"));
        assert_derivative_round_trip(parse!("x*polylog(3, 3*x^2)"));
        assert_derivative_round_trip(parse!("x^3*polylog(3, 3*x^2)"));
        assert_derivative_round_trip(parse!("x^5*polylog(3, 3*x^2)"));
        assert_derivative_round_trip(parse!("polylog(2, 5*(1 + 3*x))"));
        assert_derivative_round_trip(parse!("polylog(2, 1 + 3*x)"));
        assert_derivative_round_trip(parse!("polylog(3, 5*(1 + 3*x))"));
        assert_derivative_round_trip(parse!("polylog(3, 1 + 3*x)"));
    }

