    #[test]
    fn derivative_divides_simplifies_arcsech_logarithm_quotient() {
        let x = symbol!("x");
        let discriminant = parse!("sqrt(-c^2*d^2+e^2)");
        let u = parse!("sqrt((1-c*x)/(1+c*x))/(x*(1-c*x))");
        let v = Atom::num(1)
            + (parse!("e") - discriminant) / (parse!("c*d") * parse!("exp(asech(c*x))"));
        let target = &u * (Atom::num(1) - &v);

        assert_eq!(rubi_derivative_divides(&v, &target, x), Some(Atom::num(-1)));
        let normalized_u = parse!("1/(x*sqrt(1+c*x)*sqrt(1-c*x))");
        assert_eq!(
            rubi_derivative_divides(&v, &(&normalized_u * (Atom::num(1) - &v)), x,),
            Some(Atom::num(-1))
        );
    }

