    #[test]
    fn derivative_divides_simplifies_hyperbolic_logarithmic_derivative() {
        let x = symbol!("x");
        let y = parse!("log(tanh(x))");
        let u = parse!("sech(x)*csch(x)");

        assert_eq!(
            rubi_mathematica_hyperbolic_quotient(&parse!("tanh(x)*csch(x)/sech(x)")),
            Some(Atom::num(1)),
            "Mathematica evaluates the chained hyperbolic quotient to 1"
        );
        assert_eq!(rubi_derivative_divides(&y, &u, x), Some(Atom::num(1)));
        let double_angle_quotient = parse!("csch(2*x)") / rubi_d(&y, x);
        let exponential_quotient =
            rubi_hyperbolic_trig_to_exp(double_angle_quotient.as_view()).together();
        assert_eq!(
            exponential_quotient,
            Atom::num(1) / 2,
            "hyperbolic exponential normalization should prove the double-angle quotient; got {exponential_quotient}"
        );
        assert_eq!(
            rubi_derivative_divides(&y, &parse!("csch(2*x)"), x),
            Some(Atom::num(1) / 2),
            "Mathematica Simplify applies the hyperbolic double-angle identity"
        );
    }

    #[test]
    fn inert_fractional_product_rows_match_hyperbolic_square_root() {
        let x = symbol!("x");
        let deactivated = rubi_deactivate_trig(&parse!("sqrt(sinh(x)*tanh(x))"), x);
        let row_4898 = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(4898))
            .expect("DownValue 4898 should be registered");
        let matches_4898 = matcher_rule_for_test(&deactivated, x, row_4898).is_some();

        let argument = rubi_i() * Atom::var(x);
        let inert_product = (rubi_symbols().inert_sin.call(argument.to_owned())
            * rubi_symbols().inert_tan.call(argument))
        .sqrt();
        let row_4900 = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(4900))
            .expect("DownValue 4900 should be registered");
        let matches_4900 = matcher_rule_for_test(&inert_product, x, row_4900).is_some();

        assert!(matches_4900, "DownValue 4900 should match {inert_product}");
        assert!(matches_4898, "DownValue 4898 should match {deactivated}");
    }

