    #[test]
    fn rubi_simplerq_matches_core_numeric_and_structural_cases() {
        assert!(!rubi_simpler_q(&Atom::num(2), &Atom::num(2)));
        assert!(rubi_simpler_q(&Atom::num(2), &Atom::num(3)));
        assert!(!rubi_simpler_q(&Atom::num(-3), &Atom::num(2)));
        assert!(rubi_simpler_q(
            &(Atom::num(1) / Atom::num(3)),
            &(Atom::num(1) / Atom::num(5))
        ));
        assert!(rubi_simpler_q(&Atom::var(symbol!("a")), &parse!("a + b")));
    }

    #[test]
    fn rubi_sum_simplerq_preserves_rational_coverage_and_ports_aux_cases() {
        assert!(!rubi_sum_simpler(&(Atom::num(-1) / Atom::num(2)), 1));
        assert!(!rubi_sum_simpler(&Atom::num(-1), 1));
        assert!(rubi_sum_simpler(&Atom::num(-2), 1));
        assert!(rubi_sum_simpler(&Atom::num(-2), 2));
        assert!(rubi_sum_simpler(&Atom::num(-3), 2));
        assert!(rubi_sum_simpler(&Atom::num(1), -1));
        assert!(!rubi_sum_simpler(&(Atom::num(1) / Atom::num(2)), -1));
        assert!(!rubi_sum_simpler(&Atom::num(1), -2));
        assert!(rubi_sum_simpler(&Atom::num(2), -2));
        assert!(!rubi_sum_simpler(&parse!("m"), 1));
        assert!(rubi_sum_simpler_aux(&parse!("m - 2"), &Atom::num(1)));
        assert!(rubi_sum_simpler(&parse!("m - 3"), 1));
        assert!(!rubi_sum_simpler(&parse!("m + 2"), 1));
        assert!(rubi_sum_simpler_aux(&parse!("m + 1"), &Atom::num(-1)));
        assert!(rubi_sum_simpler_q(&Atom::num(-3), &Atom::num(2)));
        assert!(rubi_sum_simpler_q(&Atom::num(-2), &Atom::num(2)));
    }

