    #[test]
    fn rubi_pos_q_matches_together_simplify_for_radical_coefficient() {
        let bare_radical_quotient = parse!("b/sqrt(-b)");
        assert_eq!(
            rubi_simplify(&bare_radical_quotient),
            bare_radical_quotient,
            "ordinary Mathematica Simplify leaves b/Sqrt[-b] unchanged"
        );
        assert_eq!(
            rubi_together_simplify(&bare_radical_quotient),
            parse!("-sqrt(-b)"),
            "Rubi TogetherSimplify applies the stronger exact-power identity"
        );

        let coefficient = parse!("b*sqrt(-b*c+a*d)/(d*sqrt(-b)*(a-b*c/d))");
        let together = rubi_together_simplify(&coefficient);

        assert!(
            rubi_neg_q(&coefficient),
            "Rubi TogetherSimplify should give this coefficient negative form: {together}"
        );

        let external_coefficient =
            ["a", "b", "c", "d"]
                .into_iter()
                .fold(coefficient.to_owned(), |expr, name| {
                    substitute_symbol(
                        &expr,
                        symbol!(name),
                        Atom::var(Symbol::parse(name, "rubi_corpus").unwrap()),
                    )
                });
        assert!(
            rubi_neg_q(&external_coefficient),
            "the result must not depend on the caller's symbol namespace: {}",
            rubi_together_simplify(&external_coefficient)
        );

        let x = symbol!("x");
        let ratio = parse!(
            "sqrt(1+x^2*sqrt(-b)/sqrt(-c*b+d*a))/\
             sqrt(1+x^2*b*sqrt(-c*b+d*a)/(d*sqrt(-b)*(-c*b/d+a)))"
        );
        let positive_rule = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(324))
            .expect("DownValue 324 should be registered");
        let negative_rule = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(327))
            .expect("DownValue 327 should be registered");

        assert!(matcher_rule(ratio.as_view(), x, positive_rule).is_none());
        assert!(matcher_rule(ratio.as_view(), x, negative_rule).is_some());

        let integrand = parse!("(c+d*x)^(3/4)/sqrt(a+b*x)");
        assert!(
            integrate(&integrand, x).is_ok(),
            "the linear-binomial path should reach DownValue 327"
        );
    }

