    #[test]
    fn smart_apart_3822_splits_all_cubic_double_poles() {
        let x = symbol!("x");
        let q = rubi_rt(&parse!("-d/e"), 3);
        let factors = (1..=3).fold(Atom::num(1), |product, ii| {
            let phase = Atom::num(-1).pow(Atom::num(2 * ii) / 3);
            product * (&q - phase * Atom::var(x)).pow(-2)
        });
        let apart = rubi_smart_apart(&factors, x);
        let terms = rubi_add_terms(&apart);
        let double_poles = terms
            .iter()
            .filter(|term| {
                rubi_product_factors(term).iter().any(|factor| {
                    let AtomView::Pow(power) = factor.as_view() else {
                        return false;
                    };
                    integer_i64_view(power.get_exp()) == Some(-2)
                        && polynomial_degree(&power.get_base().to_owned(), x) == Some(1)
                })
            })
            .count();

        assert_eq!(
            terms.len(),
            6,
            "expected three simple and three double poles: {apart}"
        );
        assert_eq!(
            double_poles, 3,
            "expected all three cubic double poles: {apart}"
        );
    }

