    #[test]
    fn expand_to_sum_matches_downvalue_713_recurrence_payload() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let d = Atom::var(symbol!("d"));
        let e = Atom::var(symbol!("e"));
        let f = Atom::var(symbol!("f"));
        let g = Atom::var(symbol!("g"));
        let affine = &f + &g * &x_atom;
        let polynomial = (&d + &e * &x_atom).pow(3);
        let quadratic = d.pow(2) - e.pow(2) * x_atom.pow(2);
        let (quotient, remainder) = polynomial_quotient_remainder_rational_dividend(
            &polynomial,
            &affine.pow(2),
            &quadratic,
            x,
        )
        .expect("DownValue 713 rational polynomial division should succeed");
        let r = polynomial_coefficient(&remainder, x, 0).unwrap();
        let p = Atom::num(-7) / Atom::num(2);
        let a = d.pow(2);
        let c = -e.pow(2);
        let raised_p = &p + Atom::num(1);
        let raw_payload = Atom::num(2) * &a * &c * &raised_p * affine.pow(2) * quotient
            + &c * &r * (Atom::num(2) * p + Atom::num(3)) * affine.pow(2);
        let expanded = rubi_expand_to_sum(&raw_payload, x);
        let expected = parse!(
            "d^3*e^2*(e^2*f^2+10*d*e*f*g+5*d^2*g^2)/(e*f+d*g)^2 \
             -d^2*e^3*(e*f-5*d*g)*(5*e*f+3*d*g)*x/(e*f+d*g)^2 \
             +16*d^3*e^4*g^2*x^2/(e*f+d*g)^2"
        );

        assert!(
            (&expanded - &expected).together().is_zero(),
            "ExpandToSum should reproduce DownValue 713's recurrence payload: {expanded}"
        );
    }

    #[test]
    fn expand_to_sum_cancels_pseudo_rational_polynomial_like_rubi_poly_q() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let c = Atom::var(symbol!("c"));
        let d = Atom::var(symbol!("d"));
        let e = Atom::var(symbol!("e"));
        let f = Atom::var(symbol!("f"));
        let affine = &f * (&c + &d * &x_atom);
        let constant = &c * &f - &d * &e;
        let quotient = (affine.pow(4) - constant.pow(4)) / (&e + &f * &x_atom);

        assert!(rubi_poly_q(&quotient, x));
        assert_eq!(rubi_expon(quotient.as_view(), x), Some(3));
        let expanded = rubi_expand_to_sum(&quotient, x);
        assert!(
            collect_polynomial_terms(&expanded, x).is_some(),
            "{expanded}"
        );
        assert!(
            (&expanded - quotient).together().is_zero(),
            "ExpandToSum must use Rubi PolyQ's Together branch: {expanded}"
        );
    }

