    #[test]
    fn expand_cleanup_combines_opposite_affine_poles_after_polynomial_terms() {
        let x = symbol!("x");
        let split = parse!(
            "3*c*d^2/e^4+c*x^2/e^2\
             +(c*d^4+a*e^4)/(2*e^4*(-d+e*x)^2)\
             +2*c*d^3/(e^4*(-d+e*x))\
             +(c*d^4+a*e^4)/(2*e^4*(d+e*x)^2)\
             -2*c*d^3/(e^4*(d+e*x))"
        );
        let expected = parse!(
            "3*c*d^2/e^4+c*x^2/e^2\
             +(c*d^4+a*e^4)/(2*e^4*(-d+e*x)^2)\
             +(c*d^4+a*e^4)/(2*e^4*(d+e*x)^2)\
             -4*c*d^4/(e^4*(d^2-e^2*x^2))"
        );

        let cleaned = rubi_expand_cleanup(&split, x);
        assert!(
            rubi_equivalent_q(&cleaned, &expected),
            "ExpandCleanup should preserve the Mathematica value; got {cleaned}"
        );
        let has_quadratic_denominator = rubi_add_terms(&cleaned).iter().any(|term| {
            rational_numerator_denominator_unexpanded(term)
                .and_then(|(_, denominator)| collect_polynomial_terms(&denominator, x))
                .is_some_and(|terms| {
                    terms.len() == 2 && terms.contains_key(&0) && terms.contains_key(&2)
                })
        });
        assert!(
            has_quadratic_denominator,
            "ExpandCleanup should retain the quadratic denominator produced by its affine-pair rule; got {cleaned}"
        );
    }

