    #[test]
    fn integrates_inverse_tangent_exponentials_with_compound_coefficient() {
        let x_symbol = symbol!("x");
        let x = Atom::var(x_symbol);
        let a = Atom::var(symbol!("a"));
        let c = Atom::var(symbol!("c"));
        let n = Atom::var(symbol!("n"));
        let p = Atom::var(symbol!("p"));
        let angle = (&a * &x).atan();
        let quadratic = &c + a.pow(2) * x.pow(2) * &c;

        let integrands = [
            (Atom::i() * &n * &angle).exp() / x.pow(4),
            quadratic.pow(&p) / (Atom::num(2) * Atom::i() * &p * &angle).exp(),
            (Atom::i() * &n * angle).exp() * x.pow(2) * quadratic.pow(-Atom::num(1) - n.pow(2) / 2),
        ];

        for integrand in integrands {
            let primitive = integrate(&integrand, x_symbol)
                .unwrap_or_else(|_| panic!("compound coefficient should match: {integrand}"));
            assert!(
                !rubi_contains_unintegrable(&primitive),
                "compound coefficient should not defer: {integrand}; primitive: {primitive}"
            );
        }
    }

    #[test]
    fn integrates_inverse_hyperbolic_tangent_exponentials_with_compound_coefficient() {
        let x_symbol = symbol!("x");
        let x = Atom::var(x_symbol);
        let a = Atom::var(symbol!("a"));
        let c = Atom::var(symbol!("c"));
        let p = Atom::var(symbol!("p"));
        let angle = (&a * &x).atanh();
        let exponential = (Atom::num(2) * &p * &angle).exp();
        let integrands = [
            (&c - &a * &c * &x).pow(&p) / &exponential,
            (&c - &c / (&a * &x)).pow(&p) / &exponential,
            (&c - &c / (a.pow(2) * x.pow(2))).pow(&p) / &exponential,
            (Atom::num(2) * (Atom::num(1) + &p) * angle).exp()
                / (Atom::num(1) - a.pow(2) * x.pow(2)).pow(&p),
        ];

        for integrand in integrands {
            let primitive = integrate(&integrand, x_symbol)
                .unwrap_or_else(|_| panic!("compound coefficient should match: {integrand}"));
            assert!(
                !rubi_contains_unintegrable(&primitive),
                "compound coefficient should not defer: {integrand}; primitive: {primitive}"
            );
        }
    }

    #[test]
    fn normalize_integrand_applies_mathematica_trig_square_simplification() {
        let x = symbol!("x");

        assert_eq!(
            rubi_together_simplify(&parse!("1-sin(x)^2")),
            parse!("cos(x)^2")
        );
        assert_eq!(
            rubi_together_simplify(&parse!("csc(x)^3/(1-csc(x)^2)")),
            parse!("-csc(x)*sec(x)^2")
        );
        assert_eq!(
            rubi_together_simplify(&parse!("sec(x)^3/(1-sec(x)^2)")),
            parse!("-sec(x)*csc(x)^2")
        );
        assert_eq!(
            rubi_normalize_integrand(&parse!("exp(x)*(1-sin(x)^2)^(5/2)*cos(x)"), x),
            parse!("exp(x)*(cos(x)^2)^(5/2)*cos(x)")
        );
        let trig_remainder = parse!(
            "(-3/2*csc(a+b*x)+3/2*atanh(csc(a+b*x)))/b-1/2*csc(a+b*x)^3/(b*(1-csc(a+b*x)^2))"
        );
        let simplified_remainder =
            parse!("1/2*(-3*csc(a+b*x)+3*atanh(csc(a+b*x))+sec(a+b*x)^2*csc(a+b*x))/b");
        assert_eq!(
            rubi_together_simplify(&trig_remainder),
            simplified_remainder
        );
        assert_eq!(
            rubi_normalize_integrand(&(&parse!("(c+d*x)^2") * &trig_remainder), x),
            parse!("(c+d*x)^2") * simplified_remainder
        );
    }

