    #[test]
    fn simplify_integrand_splits_cancellable_log_affine_factor() {
        let x = symbol!("x");
        let integrand = parse!(
            "(x*g*e*log((x*e+d)/e)+g*d*log((x*e+d)/e)+g*d*(1-f*e/(g*d)))/(e^2*(1-x^2*c^2)^(1/2)*(x*e+d))"
        );
        let apart = integrand.apart(x);

        assert!(rubi_simplify_integrand_mathematica_simplify_candidate_q(
            &integrand, &apart, x
        ));
        assert_eq!(
            rubi_simplify_integrand_mathematica_simplify_candidate(&integrand, x),
            Some(apart.to_owned())
        );
        assert_eq!(
            rubi_simplify_integrand(&integrand, x),
            parse!(
                "g*log((d+e*x)/e)/(e^2*(1-c^2*x^2)^(1/2))+(g*d-e*f)/(e^2*(1-c^2*x^2)^(1/2)*(d+e*x))"
            )
        );

        let int_hide_form = parse!("(g*log(x+d/e)/e^2-(f*e-g*d)/(e^2*(d+e*x)))/(1-c^2*x^2)^(1/2)");
        let int_hide_apart = int_hide_form.apart(x);
        assert!(rubi_sum_q(&int_hide_apart));
        assert!(rubi_log_apart_cancellation_q(
            &int_hide_form,
            &int_hide_apart
        ));
        assert_eq!(
            rubi_simplify_integrand_mathematica_simplify_candidate(&int_hide_form, x),
            Some(int_hide_apart.to_owned())
        );
        assert_eq!(rubi_simplify_integrand(&int_hide_form, x), int_hide_apart);

        let source_integrand = parse!("(f+g*x)*(a+b*asin(c*x))/(d+e*x)^2");
        let primitive = integrate(&source_integrand, x)
            .expect("Rubi's SimplifyIntegrand path should integrate the source expression");
        assert!(
            rubi_integral_free_q(&primitive) && !rubi_contains_unintegrable(&primitive),
            "SimplifyIntegrand path should not defer: {primitive}"
        );
    }

    #[test]
    fn expand_trig_to_exp_expands_hyperbolic_squares_before_simplifying_terms() {
        let x = symbol!("x");
        let v = parse!("v");

        assert_eq!(
            rubi_hyperbolic_trig_to_exp(v.cosh().pow(2).as_view()),
            parse!("1/2+exp(2*v)/4+exp(-2*v)/4")
        );
        assert_eq!(
            rubi_hyperbolic_trig_to_exp(v.sinh().pow(2).as_view()),
            parse!("-1/2+exp(2*v)/4+exp(-2*v)/4")
        );
        let exp_positive = (Atom::num(2) * Atom::i() * &v).exp();
        let exp_negative = (-Atom::num(2) * Atom::i() * &v).exp();
        assert_eq!(
            rubi_trig_to_exp(v.cos().pow(2).as_view()),
            Atom::num(1) / 2 + &exp_positive / 4 + &exp_negative / 4
        );
        assert_eq!(
            rubi_trig_to_exp(v.sin().pow(2).as_view()),
            Atom::num(1) / 2 - exp_positive / 4 - exp_negative / 4
        );

        for source_integrand in [
            parse!("f^(a+b*x)*cosh(d+e*x+f*x^2)^2"),
            parse!("f^(a+b*x)*sinh(d+e*x+f*x^2)^2"),
        ] {
            let primitive = integrate(&source_integrand, x)
                .expect("Rubi's ExpandTrigToExp path should integrate the hyperbolic square");
            assert!(
                rubi_integral_free_q(&primitive) && !rubi_contains_unintegrable(&primitive),
                "ExpandTrigToExp path should not defer: {primitive}"
            );
        }
    }

