    #[test]
    fn rubi_poly_gcd_returns_monic_common_polynomial_factor() {
        let x = symbol!("x");
        assert_eq!(
            rubi_poly_gcd(&parse!("(1+x)^2*(2+x)"), &parse!("(1+x)*(3+x)"), x),
            Some(parse!("1+x"))
        );
        assert_eq!(
            rubi_poly_gcd(&parse!("1+x"), &parse!("2+x"), x),
            Some(Atom::num(1))
        );
        assert_eq!(
            rubi_poly_gcd(&parse!("1+x+3^(1/2)"), &parse!("1+x-3^(1/2)"), x),
            Some(Atom::num(1))
        );
        assert_eq!(
            rubi_poly_gcd(&parse!("x-2^(1/2)"), &parse!("x^2-2"), x),
            Some(parse!("-2^(1/2)+x"))
        );
        assert_eq!(
            rubi_poly_gcd(&parse!("(b-d*x)^3"), &parse!("-a*g+b*f-x*(-c*g+d*f)"), x,),
            Some(Atom::num(1))
        );
        let high_degree_gcd = rubi_poly_gcd(&parse!("(1+x)^342"), &parse!("(1+x)^2"), x)
            .expect("PolyGCD should not impose an 8-bit degree limit");
        assert!(eqq!(high_degree_gcd, (Atom::num(1) + Atom::var(x)).pow(2)));
    }

