    #[test]
    fn rubi_expand_to_sum_ports_source_shaped_parts_helpers() {
        let x = symbol!("x");
        assert!(rubi_binomial_q(parse!("1+a*x^3").as_view(), x));
        assert!(rubi_trinomial_q(&parse!("1+a*x^3+b*x^6"), x));
        assert!(!rubi_trinomial_q(&parse!("a+b*x+c*x^2"), x));
        assert!(!rubi_trinomial_q(&parse!("(a+b*x^2)^2"), x));
        assert!(rubi_generalized_binomial_q(&parse!("a*x^2+b*x^5"), x));
        assert!(rubi_generalized_trinomial_q(
            &parse!("a*x^2+b*x^5+c*x^8"),
            x
        ));
        assert!(rubi_generalized_trinomial_q(&parse!("1-(1-x^2)^3"), x));
        assert!(!rubi_generalized_trinomial_match_q(
            &parse!("1-(1-x^2)^3"),
            x
        ));

        assert_eq!(
            rubi_expand_to_sum(&parse!("(1+x)^2"), x),
            parse!("1+2*x+x^2")
        );
        assert_eq!(rubi_expand_to_sum(&parse!("1+a*x^3"), x), parse!("1+a*x^3"));
        assert_eq!(
            rubi_expand_to_sum(&parse!("1+a*x^3+b*x^6"), x),
            parse!("1+a*x^3+b*x^6")
        );
        assert_eq!(
            rubi_expand_to_sum(&parse!("a*x^2+b*x^5"), x),
            parse!("a*x^2+b*x^5")
        );
        assert_eq!(
            rubi_expand_to_sum(&parse!("a*x^2+b*x^5+c*x^8"), x),
            parse!("a*x^2+b*x^5+c*x^8")
        );
        assert_eq!(
            rubi_expand_to_sum(&parse!("1-(1-x^2)^3"), x),
            parse!("3*x^2-3*x^4+x^6")
        );
    }

