        let normalized = rubi_simplify_integrand(&expr, x);

        let AtomView::Fun(fun) = normalized.as_view() else {
            panic!("normalized expression should remain an inverse tangent: {normalized}");
        };
        assert_eq!(fun.get_symbol(), symbol!("atan"));
        let arguments = fun.into_iter().collect::<Vec<_>>();
        assert_eq!(arguments.len(), 1);
