    #[test]
    fn simplify_integrand_cancels_charlwood_38_log_derivative_quotient_like_rubi() {
        let x = symbol!("x");
        let quotient = parse!("sqrt(1+x^2)*(1+x/sqrt(1+x^2))/(x+sqrt(1+x^2))");
        let simplified_quotient = rubi_simplify_integrand(&quotient, x);
        assert_eq!(
            simplified_quotient,
            parse!("1"),
            "Rubi SimplifyIntegrand reduces the Charlwood line 38 logarithmic derivative quotient to 1"
        );

        let logarithmic = &quotient * parse!("log(1+x^2)");
        let simplified_logarithmic = rubi_simplify_integrand(&logarithmic, x);
        assert_eq!(
            simplified_logarithmic,
            parse!("log(1+x^2)"),
            "Rubi SimplifyIntegrand keeps only the logarithmic factor after reducing the quotient"
        );

        let expanded_logarithmic =
            parse!("x*log(1+x^2)/(x+sqrt(1+x^2))+sqrt(1+x^2)*log(1+x^2)/(x+sqrt(1+x^2))");
        let simplified_expanded_logarithmic = rubi_simplify_integrand(&expanded_logarithmic, x);
        assert_eq!(
            simplified_expanded_logarithmic,
            parse!("log(1+x^2)"),
            "Rubi SimplifyIntegrand should follow Mathematica Simplify before NormalizeIntegrandAux for the generated sum"
        );

        let arctangent = &quotient * parse!("atan(x)");
        let simplified_arctangent = rubi_simplify_integrand(&arctangent, x);
        assert_eq!(
            simplified_arctangent,
            parse!("atan(x)"),
            "Rubi SimplifyIntegrand keeps only the inverse tangent factor after reducing the quotient"
        );

        let expanded_arctangent =
            parse!("x*atan(x)/(x+sqrt(1+x^2))+sqrt(1+x^2)*atan(x)/(x+sqrt(1+x^2))");
        let simplified_expanded_arctangent = rubi_simplify_integrand(&expanded_arctangent, x);
        assert_eq!(
            simplified_expanded_arctangent,
            parse!("atan(x)"),
            "Rubi SimplifyIntegrand should follow Mathematica Simplify for the expanded inverse tangent quotient"
        );
    }

