    #[test]
    fn expand_integrand_product_splits_bondarenko_38_log_quadratic_remainder() {
        let x = symbol!("x");
        let i = Atom::i();
        let sqrt_three = Atom::num(3).sqrt();
        let normalized_sqrt_three = Atom::num(3) * (Atom::num(1) / Atom::num(3)).sqrt();
        let logarithmic = parse!("log(1+x+x^2)");
        let multiplier = parse!("(2+x)/(1+x+x^2)");
        let expanded = rubi_expand_integrand_product_sum(&logarithmic, &multiplier, x)
            .expect("Rubi 3.5 block 11 should split the log-quadratic remainder");
        let x_atom = Atom::var(x);
        let expected = (Atom::num(1) - &i * &normalized_sqrt_three) * &logarithmic
            / (Atom::num(1) - &i * &sqrt_three + Atom::num(2) * &x_atom)
            + (Atom::num(1) + &i * &normalized_sqrt_three) * &logarithmic
                / (Atom::num(1) + &i * &sqrt_three + Atom::num(2) * &x_atom);

        assert!(
            eqq!(expanded, expected),
            "ExpandIntegrand should match Rubi's complex split for the log-quadratic remainder; got {expanded}"
        );
    }

