    #[test]
    fn rubi_split_product_sum_base_matches_core_cases() {
        assert!(rubi_atom_base_q(&parse!("a")));
        assert!(rubi_atom_base_q(&parse!("a^3")));
        assert!(!rubi_atom_base_q(&parse!("(a + b)^3")));
        assert!(rubi_sum_base_q(&parse!("a + b")));
        assert!(rubi_sum_base_q(&parse!("(a + b)^3")));
        assert!(!rubi_sum_base_q(&parse!("(a + b)^2")));
        assert!(!rubi_sum_base_q(&parse!("a*b")));
        assert!(rubi_neg_sum_base_q(&parse!("(-2 + x)^3")));
        assert!(!rubi_neg_sum_base_q(&parse!("(2 + x)^3")));
        assert!(rubi_all_neg_term_q(&parse!("-2 - x")));
        assert!(rubi_some_neg_term_q(&parse!("2 - x")));

        let product = parse!("c*(a + b)^3*d");
        let (matched, rest) = rubi_split_product(rubi_sum_base_q, &product)
            .expect("SplitProduct[SumBaseQ, product] should find the sum-base factor");

        assert!(rubi_sum_base_q(&matched));
        assert!(
            (matched * rest - product).expand().is_zero(),
            "SplitProduct should return a factor/rest product"
        );
        assert!(rubi_atomq_split_product_sum_base(&parse!("a*b")));
        assert!(!rubi_atomq_split_product_sum_base(&parse!("a*(b + c)")));
    }

    #[test]
    fn rubi_simp_handles_algebraic_h222_argument() {
        let x = symbol!("x");
        let a = Atom::var(symbol!("a"));
        let b = Atom::var(symbol!("b"));
        let c = Atom::var(symbol!("c"));
        let d = Atom::var(symbol!("d"));
        let det = &b * &c - &a * &d;
        let argument = &b * &c / &det + &b * &d * Atom::var(x) / &det;
        let simplified = rubi_simp(&argument, x);
        let expected = &b * (&c + &d * Atom::var(x)) / det;

        assert!(
            (simplified - expected).together().is_zero(),
            "Simp should preserve Rubi H.2.2.2 affine argument"
        );
    }

