    #[test]
    fn differentiates_opaque_exponential_integral_and_gamma_arguments() {
        let x = symbol!("x");
        let x_atom = Atom::var(x);
        let ei = rubi_exp_integral_ei(x_atom.to_owned());
        let li = rubi_log_integral(x_atom.to_owned());
        let product_log = rubi_product_log(x_atom.to_owned());
        let gamma = rubi_gamma(Atom::num(3), x_atom.to_owned());
        let unary_gamma = rubi_gamma_unary(x_atom.to_owned());

        assert_eq!(ei.derivative(x), x_atom.exp() / &x_atom);
        assert_eq!(li.derivative(x), Atom::num(1) / x_atom.log());
        assert_eq!(
            rubi_d(&product_log, x),
            product_log.to_owned() / (x_atom.to_owned() * (Atom::num(1) + product_log))
        );
        assert_eq!(
            gamma.derivative(x),
            -x_atom.pow(2) * (-x_atom.to_owned()).exp()
        );
        assert_eq!(
            unary_gamma.derivative(x),
            rubi_gamma_unary(x_atom.to_owned()) * x_atom.to_owned().polygamma(Atom::num(0))
        );
        assert_eq!(
            rubi_log_gamma(x_atom.to_owned()).derivative(x),
            x_atom.polygamma(Atom::num(0))
        );
    }

