    #[test]
    fn normalizes_opaque_hypergeometric2f1_special_values() {
        let x = symbol!("x");
        let z = Atom::var(x);

        assert_eq!(
            rubi_hypergeometric2f1(Atom::num(0), Atom::num(2), Atom::num(3), z.to_owned()),
            Atom::num(1)
        );
        assert_eq!(
            rubi_hypergeometric2f1(Atom::num(2), Atom::num(3), Atom::num(3), z.to_owned()),
            (Atom::num(1) - z.to_owned()).pow(-Atom::num(2))
        );
        assert_eq!(
            rubi_hypergeometric2f1(
                Atom::num(1),
                Atom::num(1) / Atom::num(2),
                Atom::num(3) / Atom::num(2),
                z.to_owned()
            ),
            z.sqrt().atanh() / z.sqrt()
        );
        let terminating = rubi_hypergeometric2f1(
            -Atom::num(2),
            Atom::num(3) / Atom::num(2),
            Atom::num(5) / Atom::num(2),
            z.to_owned(),
        );
        let expected = Atom::num(1) - Atom::num(6) * &z / Atom::num(5)
            + Atom::num(3) * z.pow(2) / Atom::num(7);
        assert!((terminating - expected).together().is_zero());
    }

