    #[test]
    fn rubi_rule_marks_optional_wildcards_on_pattern() {
        let symbols = rubi_symbols();
        let x = symbol!("x");
        let row = Box::leak(Box::new(rubi_rule!(
            source: "Int[a_.+x_,x_Symbol]",
            desc: "Apply the matching Rubi transformation.",
            refs: [],
            pattern: symbols.a__ + symbols.x_,
            with: [a__, x_],
            optional: [a__],
            x_free: [a__],
            when: {
                freeq!(a__, x_)
            },
            rhs: {
                a__ * x_ + x_.pow(2) / Atom::num(2)
            },
        )));
        let split_row = Box::leak(Box::new(rubi_rule!(
            source: "Int[a_.+x_,x_Symbol]",
            desc: "Apply the matching Rubi transformation.",
            refs: [],
            pattern: symbols.a__ + symbols.v_,
            with: [a__, v_, x_],
            optional: [a__],
            x_free: [a__],
            when: {
                v_ == x_ && freeq!(a__, x_)
            },
            rhs: {
                a__ * x_ + x_.pow(2) / Atom::num(2)
            },
        )));

        assert_eq!(row.required, vec![symbols.a__, symbols.x_]);
        assert!(row.early_x_dependent.is_empty());
        assert_eq!(row.early_x_free, vec![symbols.a__]);
        assert_eq!(matcher_rule(parse!("y").as_view(), x, row), None);
        for integrand in [parse!("x"), parse!("2+x"), parse!("y")] {
            assert_eq!(
                matcher_rule(integrand.as_view(), x, row),
                matcher_rule(integrand.as_view(), x, split_row),
                "reserved x_ and guarded v_ must be semantically equivalent for {integrand}"
            );
        }
        assert_eq!(
            matcher_rule(parse!("x").as_view(), x, row).map(|expr| expr.expand()),
            Some(parse!("x^2/2"))
        );
        assert_eq!(
            matcher_rule(parse!("2+x").as_view(), x, row).map(|expr| expr.expand()),
            Some(parse!("2*x+x^2/2"))
        );
    }

