    fn rubi_rule_zero_bound_rejects_an_impossible_partial_match() {
        let symbols = rubi_symbols();
        let x = symbol!("x");
        let row = Box::leak(Box::new(rubi_rule!(
            order: 0,
            source: "Int[a_.+x_,x_Symbol] /; EqQ[a,0]",
            desc: "Apply the matching Rubi transformation.",
            refs: [],
            pattern: symbols.a__ + symbols.x_,
            with: [a__, x_],
            optional: [a__],
            x_free: [a__],
            zero: [a__],
            when: { freeq!(a__, x_) && eqq!(a__, 0) },
            rhs: { x_.pow(2) / Atom::num(2) },
        )));

        assert_eq!(row.early_zero, vec![symbols.a__]);
        assert!(matcher_rule(parse!("x").as_view(), x, row).is_some());
        assert_eq!(matcher_rule(parse!("2+x").as_view(), x, row), None);
    }

