    #[test]
    fn explicit_pattern_factor_bounds_separate_two_and_four_factor_rows() {
        let _ = symbol!("x");
        let two_factor = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(48))
            .expect("Rubi two-affine-factor DownValue 48 should be registered");
        let four_factor = rubi_rules()
            .iter()
            .find(|rule| rule.downvalue_order == Some(172))
            .expect("Rubi four-factor DownValue 172 should be registered");

        let two_factor_bound = two_factor
            .explicit_x_factor_bound
            .as_ref()
            .expect("two-factor row should have a structural bound");
        let four_factor_bound = four_factor
            .explicit_x_factor_bound
            .as_ref()
            .expect("four-factor row should have a structural bound");
        assert_eq!(two_factor_bound.factor_count, 2);
        assert_eq!(four_factor_bound.factor_count, 4);
        assert_eq!(four_factor_bound.affine_base_count, 4);
        assert_eq!(
            rubi_top_level_x_factor_count(
                parse!("(a+b*x)^m*(c+d*x)^n*(e+f*x)^p*(g+h*x)").as_view(),
                symbol!("x"),
            ),
            4,
        );
    }

