    #[test]
    fn trig_expand_normalizes_integer_multiples_of_arc_tangent() {
        let z = symbol!("z");
        let z_atom = Atom::var(z);
        let expression = Atom::num(2) * (Atom::num(2) * z_atom.atan()).sin()
            + (Atom::num(4) * z_atom.atan()).sin();
        let normalized = rubi_normalize_inverse_trig_trig(expression.as_view());
        let normalized = rubi_simplify(&normalized);
        let expected = Atom::num(8) * &z_atom / (Atom::num(1) + z_atom.pow(2)).pow(2);

        assert!(
            rubi_algebraic_zero_q(&(normalized - expected)),
            "TrigExpand equivalent did not normalize the ArcTan multiples"
        );
    }

