    #[test]
    fn substitution_helpers_reserve_nested_dummy_symbols() {
        let x = symbol!("x");
        let outer_guard =
            fresh_substitution_symbol().expect("the outer substitution should reserve sub1");
        assert_eq!(outer_guard.symbol(), rubi_symbols().sub1);

        let data = rubi_power_variable_expn(&parse!("sin(x^4)"), Atom::num(2), x)
            .expect("the nested substitution should use the next dummy symbol");
        assert_eq!(data.substitution_symbol, rubi_symbols().sub2);
        assert_eq!(
            data.integrand,
            parse!("sub2*sin(sub2^2)"),
            "the returned payload must retain the reserved nested symbol"
        );

        drop(data);
        drop(outer_guard);
        let next_guard =
            fresh_substitution_symbol().expect("released substitution symbols should be reusable");
        assert_eq!(next_guard.symbol(), rubi_symbols().sub1);
    }

    #[test]
    fn integrate_with_abort_separates_public_api_from_internal_cancellation() {
        let x = symbol!("x");
        let abort = AtomicBool::new(true);

        assert!(integrate_with_abort_impl(&parse!("x"), x, &abort).is_none());

        abort.store(false, AtomicOrdering::Relaxed);
        let primitive = integrate_with_abort(&parse!("x"), x)
            .expect("the internal abort flag should remain unset")
            .expect("x should integrate");
        assert!((primitive.derivative(x) - parse!("x")).expand().is_zero());
        assert_eq!(
            integrate_with_abort_impl(parse!("x").as_view(), x, &abort),
            Some(Ok(primitive))
        );

        let unfinished = integrate_with_abort_impl(&parse!("f(x)"), x, &abort)
            .expect("an unsupported integrand should not look cancelled");
        assert!(unfinished.is_err());
    }

    #[test]
    fn integrate_with_abort_stops_recursive_normalization_loop() {
        let x = symbol!("x");
        let integrand = parse!(
            "(-8-8*x-x^2-3*x^3+7*x^4+4*x^5+2*x^6)/\
             ((-1+2*x^2)^2*(1+2*x^2+4*x^3+x^4)^(1/2))"
        );
        let abort = std::sync::Arc::new(AtomicBool::new(false));
        let watchdog_abort = std::sync::Arc::clone(&abort);
        let watchdog = std::thread::spawn(move || {
            std::thread::sleep(std::time::Duration::from_millis(20));
            watchdog_abort.store(true, AtomicOrdering::Relaxed);
        });

        let started = std::time::Instant::now();
        let primitive = integrate_with_abort_impl(&integrand, x, &abort);

        watchdog.join().expect("abort watchdog should not panic");
        assert!(
            abort.load(AtomicOrdering::Relaxed),
            "watchdog should have requested abort"
        );
        assert!(
            primitive.is_none(),
            "aborted primitive leaked: {primitive:?}"
        );
        assert!(
            started.elapsed() < std::time::Duration::from_secs(60),
            "abort should stop at recursive integration boundaries"
        );
    }

