    #[test]
    fn helper_rules_follow_mathematica_downvalue_order() {
        let _ = symbol!("x");

        fn orders(rules: &[RubiRule]) -> Vec<u16> {
            rules
                .iter()
                .map(|rule| {
                    rule.downvalue_order
                        .expect("every helper row must have a Mathematica DownValue order")
                })
                .collect()
        }

        let mut expand_expected: Vec<_> = (3..=26).collect();
        expand_expected.extend([27, 27, 27]);
        expand_expected.extend(28..=38);
        expand_expected.extend([39, 39, 39, 39]);
        expand_expected.extend(40..=45);

        assert_eq!(orders(rubi_expand_integrand_rules()), expand_expected);
        assert_eq!(orders(rubi_deactivate_trig_rules()), [1]);
        assert_eq!(
            orders(rubi_fix_inert_trig_function_rules()),
            (1..=60).collect::<Vec<_>>()
        );
        assert_eq!(
            orders(rubi_unify_inert_trig_function_rules()),
            (1..=75).collect::<Vec<_>>()
        );
    }
